-- Squashed from 5 prior migrations (see git log) on 2026-05-04.
-- App: itinerary-planner. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_itinerary_planner DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    trip_id uuid NOT NULL,
    day_index integer DEFAULT 0 NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    title text NOT NULL,
    kind text DEFAULT 'sightseeing'::text NOT NULL,
    date timestamp with time zone,
    start_time text,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    location_name text,
    latitude numeric(10,6),
    longitude numeric(10,6),
    address text,
    notes text,
    cost_cents bigint DEFAULT 0 NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    booking_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone
);


