--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--
-- Mirrors @molecule/api-resource-payment/src/__setup__/payments.sql so the squashed
-- migration brings the payments table even when the per-app migrate.ts in
-- this template predates the workspace's __setup__/*.sql replay step
-- (mlcl/templates/api/migrate.ts.tpl). Stripe webhook handlers in
-- @molecule/api-payments-stripe call payments.findByUserId on every plan-
-- change request — without this table, every billing flow logs
-- 'relation "payments" does not exist' and the upgrade silently no-ops.

CREATE TABLE IF NOT EXISTS public.payments (
    id uuid UNIQUE PRIMARY KEY NOT NULL,
    "createdAt" timestamptz DEFAULT current_timestamp NOT NULL,
    "updatedAt" timestamptz DEFAULT current_timestamp NOT NULL,
    "userId" uuid NOT NULL,
    "transactionId" text,
    "productId" text,
    "platformKey" text,
    "data" jsonb,
    "receipt" text
);
CREATE INDEX IF NOT EXISTS "payments_createdAt_index" ON public.payments ("createdAt");
CREATE INDEX IF NOT EXISTS "payments_updatedAt_index" ON public.payments ("updatedAt");
CREATE INDEX IF NOT EXISTS "payments_userId_index" ON public.payments ("userId");
CREATE INDEX IF NOT EXISTS "payments_transactionId_index" ON public.payments ("transactionId");
CREATE INDEX IF NOT EXISTS "payments_productId_index" ON public.payments ("productId");
CREATE INDEX IF NOT EXISTS "payments_platformKey_index" ON public.payments ("platformKey");


